# generated by tools/ail2py.py from c_float32_filter.ail; edit the .ail until onelang s16
from ail import read_bytes, write_bytes
import sys

def smooth(values: list[float]) -> list[float]:
    weights = [0.25, 0.5, 0.25]
    return filter_values(values, weights)

def main() -> int:
    try:
        values = []
        for word in read_bytes(sys.argv[1]).decode().split():
            values.append(float(word))
        result = smooth(values)
        release_values()
        output = []
        for value in result:
            bits = float_bits(value)
            output.append(bits % 256)
            output.append(bits // 256 % 256)
            output.append(bits // 65536 % 256)
            output.append(bits // 16777216)
        write_bytes(sys.argv[2], bytes(output))
        return 0
    except ValueError:
        print('invalid input')
        return 2
    except OSError:
        print('file error')
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
